def find_evidence(source_name: str, location: str, excerpt: str) -> tuple[str, str]:
    source = source_by_name[source_name]
    items = source.get("items", [])
    target = compact(excerpt).lower()
    exact_location = [item for item in items if item.get("location") == location]
    for item in exact_location:
        if target and target in compact(item.get("text", "")).lower():
            return item["id"], item["location"]
    if exact_location:
        return exact_location[0]["id"], exact_location[0]["location"]
    for item in items:
        if target and target in compact(item.get("text", "")).lower():
            return item["id"], item["location"]
    raise ValueError(f"근거를 찾지 못했습니다: {source_name} / {location} / {excerpt}")


questions: list[dict[str, object]] = []
missing: list[str] = []
for index, item in enumerate(CONCEPTS, start=1):
    source_id = source_by_name[item["source"]]["id"]
    try:
        evidence_id, resolved_location = find_evidence(item["source"], item["location"], item["evidence"])
    except ValueError as error:
        missing.append(str(error))
        evidence_id, resolved_location = source_by_name[item["source"]]["items"][0]["id"], item["location"]
    for suffix, answer, statement in (("o", True, item["true"]), ("x", False, item["false"])):
        questions.append(
            {
                "id": f"q-c{index:03d}-{suffix}",
                "sourceId": source_id,
                "source": item["source"],
                "location": resolved_location,
                "evidenceId": evidence_id,
                "topic": item["topic"],
                "concept": item["concept"],
                "kind": "개념 확인",
                "statement": statement,
                "answer": answer,
                "evidence": item["evidence"],
                "explanation": item["explanation"],
                "number": len(questions) + 1,
            }
        )

counts = Counter(question["source"] for question in questions)
for source in source_data["sources"]:
    source["questionCount"] = counts.get(source["name"], 0)
source_data["questionCount"] = len(questions)
source_data["questionMode"] = "concept-curated"

QUESTIONS_PATH.write_text(json.dumps({
    "version": 2,
    "title": "고니 자료 개념 중심 OX 퀴즈",
    "generatedFrom": r"C:\Users\wizju\Downloads\고니",
    "sourceCount": len(source_data["sources"]),
    "questionCount": len(questions),
    "conceptCount": len(CONCEPTS),
    "topics": [
        {"name": topic, "count": sum(1 for q in questions if q["topic"] == topic)}
        for topic in dict.fromkeys(q["topic"] for q in questions)
    ],
    "questions": questions,
}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

SOURCES_PATH.write_text(json.dumps(source_data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

source_stats = []
for source in source_data["sources"]:
    source_concepts = sum(1 for item in CONCEPTS if item["source"] == source["name"])
    source_stats.append({
        "name": source["name"],
        "format": source["format"],
        "rawItemCount": source["itemCount"],
        "curatedConceptCount": source_concepts,
        "questionCount": source["questionCount"],
    })

COVERAGE_PATH.write_text(json.dumps({
    "generatedFrom": r"C:\Users\wizju\Downloads\고니",
    "sourceCount": len(source_data["sources"]),
    "rawItemCount": sum(source["itemCount"] for source in source_data["sources"]),
    "curatedConceptCount": len(CONCEPTS),
    "questionCount": len(questions),
    "trueCount": sum(1 for q in questions if q["answer"]),
    "falseCount": sum(1 for q in questions if not q["answer"]),
    "sourceStats": source_stats,
    "method": "자료에서 개념을 선별해 한 문항에 하나의 개념만 담고, 개념별 O/X 문장·해설·원문 위치를 수동 큐레이션했다. 제목·진행 시간·발표자 노트·표 형식은 문항에서 제외했다.",
    "missingEvidenceWarnings": missing,
}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

